WITH fixes(slug,pos,q,a,why) AS (VALUES ('pcac-2026-rlm-medias-graficos-tabelas-interpretacao',1,'A média aritmética simples dos valores 5, 9, 10 e 12 é 9.',true,'Certo. Some 5+9+10+12=36 e divida pela quantidade de valores, 4. Assim, a média simples é 9.'),('pcac-2026-rlm-progressao-aritmetica-geometrica',1,'A sequência 6, 10, 14, 18 é uma progressão aritmética de razão 4.',true,'Certo. Em uma PA a diferença entre termos consecutivos é constante. Aqui 10−6=14−10=18−14=4.'),('pcac-2026-rlm-progressao-aritmetica-geometrica',2,'A sequência 3, 12, 48, 192 é uma progressão geométrica de razão 4.',true,'Certo. Em uma PG a razão entre termos consecutivos é constante: 12/3=48/12=192/48=4.'),('pcac-2026-rlm-probabilidade-uniao-condicional-independencia',6,'Se dois eventos são mutuamente exclusivos, então a probabilidade de sua interseção é zero.',true,'Certo. Eventos mutuamente exclusivos não ocorrem simultaneamente, portanto P(A∩B)=0. Isso não significa que sejam independentes.'),('pcac-2026-rlm-medias-graficos-tabelas-interpretacao',9,'No conjunto 2, 2, 2 e 10, a média é 4 e a mediana é 2.',true,'Certo. A média é (2+2+2+10)/4=4. A mediana é a média dos dois valores centrais ordenados: (2+2)/2=2. Os indicadores podem diferir.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL THEN jsonb_set(jsonb_set(jsonb_set(e.value,'{q}',to_jsonb(f.q)),'{a}',to_jsonb(f.a)),'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;